61: export function coverageFromSamples(
62:   samples: readonly PulseSample[],
63:   startUs: number,
64:   stopUs: number,
65:   floor = CONFIDENCE_FLOOR,
66: ): NonNullable<SessionMeta['coverage']> {
67:   if (stopUs < startUs) throw new Error('The session clock moved backwards.');
68:   const totalUs = stopUs - startUs;
69:   const ordered = samples
70:     .filter((sample) => sample.tUs >= startUs && sample.tUs <= stopUs)
71:     .sort((a, b) => a.tUs - b.tUs);
72:   let usableUs = 0;
73:   for (let index = 0; index < ordered.length; index += 1) {
74:     const sample = ordered[index];
75:     if (!isUsableSample(sample, floor)) continue;
76:     const nextUs = index + 1 < ordered.length ? ordered[index + 1].tUs : stopUs;
77:     const gap = nextUs - sample.tUs;
78:     if (gap <= 0) continue;
79:     usableUs += Math.min(gap, SAMPLE_HOLD_US);
80:   }
81:   if (usableUs > totalUs) usableUs = totalUs;
82:   const pct = totalUs === 0 ? 0 : (usableUs / totalUs) * 100;
83:   return { usableUs, totalUs, pct, confidenceFloor: floor };
84: }
